From ad78da82c2aa598f8b3686371b8d02ba6252449d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:26:20 +0100
Subject: [PATCH] shell: don't copy the old config to a variant of the same
 applet

Switching a System Monitor widget to another one through Show
Alternatives copied the old config over the new widget, and since these
widgets only differ by their config, nothing changed. Now we skip that.

BUG: 467392
---
 shell/alternativeshelper.cpp | 12 ++++++++----
 1 file changed, 8 insertions(+), 4 deletions(-)

diff --git a/shell/alternativeshelper.cpp b/shell/alternativeshelper.cpp
index fd911c9bf3..21dc489ad5 100644
--- a/shell/alternativeshelper.cpp
+++ b/shell/alternativeshelper.cpp
@@ -65,10 +65,14 @@ void AlternativesHelper::loadAlternative(const QString &plugin)

     if (newApplet) {
         newApplet->setGlobalShortcut(shortcut);
-        KConfigGroup newCg(newApplet->config());
-        m_applet->config().copyTo(&newCg);
-        // To let ConfigPropertyMap reload its config
-        Q_EMIT newApplet->configScheme()->configChanged();
+        // Variants of the same root applet differ only by their config
+        const QString oldRoot = m_applet->pluginMetaData().value(u"X-Plasma-RootPath", m_applet->pluginMetaData().pluginId());
+        if (oldRoot != newApplet->pluginMetaData().value(u"X-Plasma-RootPath")) {
+            KConfigGroup newCg(newApplet->config());
+            m_applet->config().copyTo(&newCg);
+            // To let ConfigPropertyMap reload its config
+            Q_EMIT newApplet->configScheme()->configChanged();
+        }
     }

     m_applet->destroy();
